function btreeHeight(rows, fanout) {
  // levels needed so fanout^levels >= rows
  let capacity = fanout;
  let height = 1;
  while (capacity < rows) {
    capacity *= fanout;
    height++;
  }
  return height;
}
const rows = 200000000;
const fanout = 256;
const h = btreeHeight(rows, fanout);
const pageReads = h + 1; // descend h index pages, then 1 heap fetch via TID
console.log(`height=${h} pageReads=${pageReads}`);
